import{_ as o,o as s,c as a,a2 as t}from"./chunks/framework.Di-jvWLj.js";const u=JSON.parse('{"title":"Workspaces & Coding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/workspaces.md","filePath":"guide/workspaces.md","lastUpdated":1793547867000}'),n={name:"guide/workspaces.md"};function c(r,e,d,i,l,p){return s(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="workspaces-coding" tabindex="-1">Workspaces &amp; Coding <a class="header-anchor" href="#workspaces-coding" aria-label="Permalink to &quot;Workspaces &amp; Coding&quot;">​</a></h1><p>An agent that reproduces a bug, runs tests or fixes code needs a place to run commands. chamvi gives each run <strong>disposable workspaces</strong>: a directory, optionally a checkout of a git repository with its history, in which the model runs commands and edits files through tools. Workspaces come from a <strong>sandbox provider</strong> and are held by a <strong>workspace manager</strong> that disposes them when the run settles.</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">npm </span><span style="color:#E7C58C;">install</span><span style="color:#E7C58C;"> @chamvi/sandbox</span><span style="color:#E7C58C;"> @chamvi/coding</span><span style="color:#E7C58C;"> @chamvi/sandbox-docker</span></span></code></pre></div><h2 id="providers" tabindex="-1">Providers <a class="header-anchor" href="#providers" aria-label="Permalink to &quot;Providers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Provider</th><th>Package</th><th>A workspace is</th><th>Isolation</th></tr></thead><tbody><tr><td>local</td><td><a href="/reference/sandbox#chamvi-sandbox-local"><code>@chamvi/sandbox-local</code></a></td><td>a temporary directory on the host</td><td><strong>none</strong>: development and tests only</td></tr><tr><td>Docker</td><td><a href="/reference/sandbox#chamvi-sandbox-docker"><code>@chamvi/sandbox-docker</code></a></td><td>one container</td><td>root inside with a writable root and only the package-manager capabilities, <code>no-new-privileges</code>, cpu, memory and pid limits</td></tr><tr><td>Kubernetes</td><td><a href="/reference/sandbox#chamvi-sandbox-k8s"><code>@chamvi/sandbox-k8s</code></a></td><td>one pod</td><td>the same, no service account token, resource limits</td></tr></tbody></table><p>All three pass the same workspace contract (<code>describeWorkspaceContract</code> from <code>@chamvi/test-kit</code>): argv-only exec, path checks, output caps, process-group kills on timeout, and dispose semantics.</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> provider = createDockerSandbox({</span></span>
<span class="line"><span style="color:#958A8B;">    // pin a digest in production</span></span>
<span class="line"><span style="color:#E6DFDE;">    image: </span><span style="color:#E7C58C;">&#39;ghcr.io/chamvi/sandbox-dev:trixie&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#958A8B;">    // a bridge without inter-container traffic, firewalled from the host</span></span>
<span class="line"><span style="color:#E6DFDE;">    network: </span><span style="color:#E7C58C;">&#39;chamvi-sandbox&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    limits: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        cpu: </span><span style="color:#E7C58C;">&#39;2&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        memory: </span><span style="color:#E7C58C;">&#39;4Gi&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        pids: </span><span style="color:#E7C58C;">1024</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// in-cluster service account or KUBECONFIG</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> provider = createKubernetesSandbox({</span></span>
<span class="line"><span style="color:#E6DFDE;">    namespace: </span><span style="color:#E7C58C;">&#39;agents-sandbox&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    podLabels: { </span><span style="color:#E7C58C;">&#39;example.com/egress&#39;</span><span style="color:#E6DFDE;">: </span><span style="color:#E7C58C;">&#39;restricted&#39;</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">    limits: {</span></span>
<span class="line"><span style="color:#E6DFDE;">        cpu: </span><span style="color:#E7C58C;">&#39;2&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        memory: </span><span style="color:#E7C58C;">&#39;4Gi&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        storage: </span><span style="color:#E7C58C;">&#39;8Gi&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The container providers use <code>ghcr.io/chamvi/sandbox-dev:trixie</code> by default (Debian, git, curl, ripgrep, jq, build-essential, <code>tini</code> and <a href="https://mise.jdx.dev" target="_blank" rel="noreferrer">mise</a>), built for <code>linux/amd64</code> and <code>linux/arm64</code>. It ships no language toolchain: the model installs what the repository needs, <code>mise use -g node@24</code> or <code>mise install</code> (which reads <code>.tool-versions</code>, <code>mise.toml</code>, <code>.nvmrc</code> and <code>.python-version</code>), and system packages with <code>apt-get</code>. Pin a digest in production. See <a href="/deployment/docker#sandbox-image">Docker Image</a>.</p><h3 id="usable-inside-strict-at-the-edge" tabindex="-1">Usable inside, strict at the edge <a class="header-anchor" href="#usable-inside-strict-at-the-edge" aria-label="Permalink to &quot;Usable inside, strict at the edge&quot;">​</a></h3><p>Inside a Docker or Kubernetes workspace the model may do what a developer does on a throwaway machine: it runs as <strong>root</strong> with a <strong>writable root filesystem</strong>, so <code>apt-get install</code>, <code>npm install -g</code> and any installer work without an approval. The container is the boundary: no privileged mode, every capability dropped but <code>CHOWN</code>, <code>DAC_OVERRIDE</code>, <code>FOWNER</code>, <code>FSETID</code>, <code>SETUID</code>, <code>SETGID</code> and <code>KILL</code>, <code>no-new-privileges</code>, the cpu, memory and pid limits, and no host mount but the package cache.</p><p>Where that is too much, the providers&#39; <strong>hardened mode</strong> restores a non-root user and a read-only root (no capability at all; toolchains still install into HOME through mise, <code>apt</code> does not work):</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#E6DFDE;">createDockerSandbox({ user: </span><span style="color:#E7C58C;">&#39;1000:1000&#39;</span><span style="color:#E6DFDE;">, readOnlyRoot: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#E6DFDE;">createKubernetesSandbox({ namespace: </span><span style="color:#E7C58C;">&#39;agents-sandbox&#39;</span><span style="color:#E6DFDE;">, user: { uid: </span><span style="color:#E7C58C;">1000</span><span style="color:#E6DFDE;">, gid: </span><span style="color:#E7C58C;">1000</span><span style="color:#E6DFDE;"> }, readOnlyRoot: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;"> });</span></span></code></pre></div><p>On Kubernetes the default needs a namespace whose Pod Security admits root pods (<code>baseline</code>); the hardened mode fits <code>restricted</code>. See <a href="/deployment/kubernetes#pod-security">Kubernetes</a>.</p><h3 id="images-the-model-may-pick" tabindex="-1">Images the model may pick <a class="header-anchor" href="#images-the-model-may-pick" aria-label="Permalink to &quot;Images the model may pick&quot;">​</a></h3><p><code>create_workspace({ image })</code> lets the model pick an image (<code>python:3.13</code>, <code>rust:1</code>, <code>ghcr.io/acme/builder:2</code>) only from an allow-list you configure: the manager&#39;s <code>allowImage(image)</code>, or with <code>sandboxModule()</code> the <code>CHAMVI_SANDBOX_IMAGES</code> comma list of exact references (it wins over <code>allowImage</code>). Without one, and always on the local provider (it runs no images), the tool has no <code>image</code> parameter and a requested image is a <code>ValidationError</code>. The model never gets more cpu, memory, lifetime or workspaces than you configured. The provider&#39;s pull policy (<code>pull</code> on Docker, <code>imagePullPolicy</code> on Kubernetes) applies to every image, also one the model picked. The image&#39;s entrypoint is replaced, so an image whose entrypoint is a command works too. An image needs <code>sh</code>, <code>git</code> and a GNU <code>timeout</code> that takes <code>-k</code>: the provider probes them before the checkout and fails with a message naming what is missing (busybox images lack a <code>timeout -k</code> on old versions, <code>debian:*-slim</code> lacks git).</p><h3 id="the-package-cache" tabindex="-1">The package cache <a class="header-anchor" href="#the-package-cache" aria-label="Permalink to &quot;The package cache&quot;">​</a></h3><p>Every container and pod mounts <code>/cache</code> and sets <code>XDG_CACHE_HOME</code>, <code>npm_config_cache</code>, <code>PIP_CACHE_DIR</code>, <code>GOMODCACHE</code>, <code>GOCACHE</code>, <code>COMPOSER_CACHE_DIR</code> into it (local: <code>&lt;root&gt;/.cache</code>): package downloads only. Toolchains stay per workspace (mise keeps its installs in <code>$HOME/.local/share/mise</code>), and so do homes that keep credentials or installed programs stay per workspace (<code>CARGO_HOME</code>, which holds <code>cargo login</code>&#39;s <code>credentials.toml</code> and <code>cargo install</code>ed binaries, stays <code>$HOME/.cargo</code>; npm&#39;s <code>.npmrc</code> stays in <code>$HOME</code>). <code>HOME</code> is <code>/home/sandbox</code>, a disk-backed volume of the workspace (kept when a stopped container restarts, removed with the workspace), never the memory-backed <code>/tmp</code>, so cargo, rustup, Maven and Gradle homes and mise&#39;s global config and shims count neither against <code>tmpSize</code> nor the memory limit. By default the cache is per workspace: an anonymous volume on Docker, an emptyDir per pod on Kubernetes. To share downloads between workspaces name a volume (<code>cache: { volume }</code> on Docker) or a ReadWriteMany claim (<code>cache: { claimName }</code> on Kubernetes). <code>/tmp</code> is a 1 GiB tmpfs (<code>tmpSize</code>).</p><div class="warning custom-block"><p class="custom-block-title">A shared cache is shared trust</p><p>A named volume or claim is a trust boundary shared by every run and agent using it. A malicious package one run fetched can sit in another run&#39;s cache: npm verifies integrity hashes, pip, Go&#39;s build cache and others less. Share a cache only between runs that trust each other, one volume per trust level (local shares <code>&lt;root&gt;/.cache</code> unless <code>cache: false</code>).</p><p>chamvi&#39;s own commands never run from the cache: every workspace command starts with every <code>/cache</code> folder dropped from <code>PATH</code>, so a <code>git</code> or <code>timeout</code> one run planted there is not what the next workspace&#39;s checkout runs, and <code>sandbox-dev</code> keeps mise&#39;s toolchains and shims in the workspace&#39;s HOME. Never put a <code>/cache</code> folder on an image&#39;s or the <code>env</code>&#39;s <code>PATH</code> (the container runtime resolves the first <code>sh</code> with it).</p></div><h2 id="the-manager-and-its-tools" tabindex="-1">The manager and its tools <a class="header-anchor" href="#the-manager-and-its-tools" aria-label="Permalink to &quot;The manager and its tools&quot;">​</a></h2><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> workspaces = createWorkspaceManager({</span></span>
<span class="line"><span style="color:#E6DFDE;">    provider,</span></span>
<span class="line"><span style="color:#958A8B;">    // only your own repositories; the model cannot clone anything else</span></span>
<span class="line"><span style="color:#E6DFDE;">    allowRepo: (url) </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> url.startsWith(</span><span style="color:#E7C58C;">&#39;https://github.com/acme/&#39;</span><span style="color:#E6DFDE;">),</span></span>
<span class="line"><span style="color:#E6DFDE;">    limits: { maxLifetimeMs: </span><span style="color:#E7C58C;">20</span><span style="color:#E6DFDE;"> * </span><span style="color:#E7C58C;">60_000</span><span style="color:#E6DFDE;"> },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> repro = defineAgent({</span></span>
<span class="line"><span style="color:#E6DFDE;">    name: </span><span style="color:#E7C58C;">&#39;repro&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    model,</span></span>
<span class="line"><span style="color:#E6DFDE;">    instructions: </span><span style="color:#E7C58C;">&#39;Check out the repository from the payload, write a failing test for the reported bug, &#39;</span><span style="color:#E6DFDE;"> +</span></span>
<span class="line"><span style="color:#E7C58C;">        &#39;run it and answer with the output and the diff.&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [http.on()],</span></span>
<span class="line"><span style="color:#E6DFDE;">    tools: { ...workspaces.tools(), ...codingTools(workspaces) },</span></span>
<span class="line"><span style="color:#E6DFDE;">    hooks: {</span></span>
<span class="line"><span style="color:#958A8B;">        // the coding tools are not yours: gate bash here, every command waits for a human</span></span>
<span class="line"><span style="color:#FF7B84;">        async</span><span style="color:#E6DFDE;"> beforeToolExecution({ toolName, input }, ctx) {</span></span>
<span class="line"><span style="color:#FF7B84;">            if</span><span style="color:#E6DFDE;"> (toolName !== </span><span style="color:#E7C58C;">&#39;bash&#39;</span><span style="color:#E6DFDE;">) {</span></span>
<span class="line"><span style="color:#FF7B84;">                return</span><span style="color:#E6DFDE;"> input;</span></span>
<span class="line"><span style="color:#E6DFDE;">            }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> { command } = input </span><span style="color:#FF7B84;">as</span><span style="color:#E6DFDE;"> { command: string };</span></span>
<span class="line"><span style="color:#FF7B84;">            const</span><span style="color:#E6DFDE;"> decision = </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> approve(ctx, { title: </span><span style="color:#E7C58C;">&#39;Run a shell command?&#39;</span><span style="color:#E6DFDE;">, body: command });</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">            if</span><span style="color:#E6DFDE;"> (</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">decision.approved) {</span></span>
<span class="line"><span style="color:#FF7B84;">                throw</span><span style="color:#FF7B84;"> new</span><span style="color:#E6DFDE;"> ToolDeniedError(</span><span style="color:#E7C58C;">\`Command refused: </span><span style="color:#E6DFDE;">\${</span><span style="color:#E7C58C;">decision</span><span style="color:#E6DFDE;">.</span><span style="color:#E7C58C;">reason </span><span style="color:#FF7B84;">??</span><span style="color:#E7C58C;"> &#39;denied&#39;</span><span style="color:#E6DFDE;">}</span><span style="color:#E7C58C;">\`</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">            }</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">            return</span><span style="color:#E6DFDE;"> input;</span></span>
<span class="line"><span style="color:#E6DFDE;">        },</span></span>
<span class="line"><span style="color:#E6DFDE;">    },</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> engine = </span><span style="color:#FF7B84;">new</span><span style="color:#E6DFDE;"> Engine({</span></span>
<span class="line"><span style="color:#E6DFDE;">    store,</span></span>
<span class="line"><span style="color:#E6DFDE;">    agents: [repro],</span></span>
<span class="line"><span style="color:#E6DFDE;">    channels: [httpChannel()],</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span>
<span class="line"></span>
<span class="line"><span style="color:#958A8B;">// a run&#39;s workspaces go once it completed, failed or was cancelled</span></span>
<span class="line"><span style="color:#E6DFDE;">workspaces.attach(engine);</span></span>
<span class="line"><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> engine.start();</span></span>
<span class="line"></span>
<span class="line"><span style="color:#E6DFDE;">process.once(</span><span style="color:#E7C58C;">&#39;SIGTERM&#39;</span><span style="color:#E6DFDE;">, </span><span style="color:#FF7B84;">async</span><span style="color:#E6DFDE;"> () </span><span style="color:#FF7B84;">=&gt;</span><span style="color:#E6DFDE;"> {</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> engine.drain({ timeoutMs: </span><span style="color:#E7C58C;">25_000</span><span style="color:#E6DFDE;"> });</span></span>
<span class="line"><span style="color:#958A8B;">    // after the drain: runs still executing keep their workspaces until then</span></span>
<span class="line"><span style="color:#FF7B84;">    await</span><span style="color:#E6DFDE;"> workspaces.close();</span></span>
<span class="line"><span style="color:#E6DFDE;">    process.exit(</span><span style="color:#E7C58C;">0</span><span style="color:#E6DFDE;">);</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><p>The coding tools are not yours to edit, so the approval for <code>bash</code> sits in the agent&#39;s <code>beforeToolExecution</code> hook: <code>approve()</code> there pauses the run (keeping its workspaces on this replica) until someone answers, and a refused command reaches the model as a <code>ToolDeniedError</code> tool error. See <a href="/guide/approvals#gating-tools-you-did-not-write">Approvals &amp; Hooks</a>.</p><p><code>workspaces.tools()</code> gives the model six tools by default; <code>codingTools(workspaces)</code> adds eleven more. Every tool resolves its workspace with the calling run&#39;s id, so a run can only reach its own workspaces.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Package</th><th>What it does</th></tr></thead><tbody><tr><td><code>create_workspace</code></td><td>sandbox</td><td><code>{ repo?, ref?, image? }</code>: a checkout of <code>repo</code> at <code>ref</code> with its history and the default branch beside it (<code>defaultBranch</code>), or an empty git repository, in the image asked for; the same repository again returns the same workspace (<code>reused: true</code>)</td></tr><tr><td><code>read_repository_instructions</code></td><td>sandbox</td><td><code>{ paths?, workspace? }</code>: current guidance for root and requested ancestors, with provenance and diagnostics; omitted when the manager disables collection</td></tr><tr><td><code>dispose_workspace</code></td><td>sandbox</td><td><code>{ workspace? }</code>: disposes one workspace</td></tr><tr><td><code>git_fetch</code></td><td>sandbox</td><td><code>{ remote?, refspec? }</code>: fetches with the run&#39;s credentials, every branch into <code>origin/*</code> by default</td></tr><tr><td><code>git_pull</code></td><td>sandbox</td><td><code>{ remote?, branch?, rebase? }</code>: fetches a branch and merges it, or rebases onto it; conflicts come back in the result</td></tr><tr><td><code>git_push</code></td><td>sandbox</td><td><code>{ remote?, branch?, force?, setUpstream? }</code>: pushes under the <a href="#structured-git-tools-and-policy-scope">push policy</a></td></tr><tr><td><code>read_file</code></td><td>coding</td><td>A line range of a text file (at most 2000 lines, 65 536 characters, files up to 16 MiB); an image as an image the model sees; any file up to 1 MiB as base64; the output logs of <code>bash</code></td></tr><tr><td><code>write_file</code></td><td>coding</td><td>Replaces a file (text, or bytes as base64), creating directories</td></tr><tr><td><code>edit_file</code></td><td>coding</td><td>Replaces an exact string, once (or every match with <code>replaceAll</code>); edits and writes of one file run one after the other, so several in one step all apply</td></tr><tr><td><code>multi_edit</code></td><td>coding</td><td>Several exact-string edits of one file in order; nothing is written when one fails</td></tr><tr><td><code>grep</code></td><td>coding</td><td>ripgrep when the image has it, else <code>git grep -E</code>, else <code>grep -rE</code>; hidden files always, git-ignored ones with <code>includeIgnored</code></td></tr><tr><td><code>glob</code></td><td>coding</td><td>Files by a <code>**</code> pattern, git-ignored ones with <code>includeIgnored</code></td></tr><tr><td><code>list_files</code></td><td>coding</td><td>Tracked and untracked files, git-ignored ones with <code>includeIgnored</code></td></tr><tr><td><code>bash</code></td><td>coding</td><td>A shell that keeps its working directory and exported variables between calls; long output in a log file with an excerpt in the result; <code>background: true</code> for servers and watchers</td></tr><tr><td><code>bash_output</code></td><td>coding</td><td>New output and the status of a background job, from a byte offset</td></tr><tr><td><code>bash_kill</code></td><td>coding</td><td>Stops a background job and every process it started</td></tr><tr><td><code>git_diff</code></td><td>coding</td><td><code>git status --short</code> and the unified diff</td></tr></tbody></table><p>The coding tools take an optional <code>workspace</code> id; omitted, they use the run&#39;s only workspace. The model sees every workspace at <code>/workspace</code>, whatever the provider maps it to. See the <a href="/reference/coding"><code>@chamvi/coding</code> reference</a> for inputs and results.</p><p>With <a href="/guide/app#modules"><code>@chamvi/app</code></a>, <code>sandboxModule()</code> (<code>@chamvi/sandbox/module</code>) builds the manager, attaches and closes it and provides it on the engine: a tools factory takes it with <code>injectSandboxContext(ctx)</code> and builds <code>manager.tools()</code> and <code>codingTools(manager)</code> per execution, without importing the module instance (see <a href="/guide/tools#context-shared-instances-for-tools">Context</a>). A hand-built engine calls <code>provideSandboxContext(engine, manager)</code> once after <code>new Engine()</code>.</p><p>A run may hold <code>maxWorkspacesPerRun</code> (3) workspaces at once; raise it on the manager (<code>createWorkspaceManager({ maxWorkspacesPerRun })</code>), and the tool error says so. Repositories are <code>owner/name</code> (GitHub) or an <code>https:</code> URL without credentials, query or fragment; <code>allowRepo</code> narrows them, <code>allowFileRepos</code> adds <code>file:///absolute/path</code> for development. Refs are plain branch, tag or commit names that git can never read as an option or a range.</p><h2 id="repository-instructions" tabindex="-1">Repository instructions <a class="header-anchor" href="#repository-instructions" aria-label="Permalink to &quot;Repository instructions&quot;">​</a></h2><p>A repository-backed <code>create_workspace</code> returns root <code>instructions</code> alongside its workspace metadata; a repo-less create returns <code>instructions: null</code>. <code>read_file</code> attaches applicable <code>instructions</code> to ordinary UTF-8 text results of a repository-backed workspace (a repo-less one runs no collector). When collection fails (an image without <code>head</code>, <code>base64</code> or <code>tr</code> in <code>/usr/bin</code> or <code>/bin</code>, a stray stderr line, an exec timeout), both answer <code>instructions: null</code> with an <code>instructionsError</code> reason instead of failing: the workspace and the file read stay usable, and <code>read_repository_instructions</code> can retry. Images, base64 reads and HOME logs have no attachment. The context is delivered in ordinary tool messages, so the model receives it and existing steps and checkpoints retain it across approval pauses and restarts.</p><p>For <code>packages/api/src/a.ts</code>, discovery reads entrypoints in root, <code>packages</code>, <code>packages/api</code> and <code>packages/api/src</code>, without scanning siblings. An existing directory includes its own guidance; a missing target uses its parent. Directories are ordered root first, then depth and JavaScript string order, with <code>AGENTS.md</code> before <code>CLAUDE.md</code> in each. A standalone <code>@relative/path</code> line expands a guide depth-first in textual order, relative to the including file; <code>..</code> must stay inside the workspace. Surrounding whitespace is allowed, whitespace within the path is not. Inline <code>@</code> text, Markdown links and matching backtick/tilde fences of three or more characters do not expand includes. Absolute paths, URLs, home paths, NUL and escapes are refused.</p><p>Every source records its canonical <code>path</code>, exact-byte <code>sha256</code>, redacted UTF-8 <code>content</code>, entrypoint-directory <code>scopes</code> and <code>includedBy</code> parent paths. Included files inherit the entrypoint scope; deduplication retains all scopes and parents. <code>commit</code> is the recorded checkout commit or <code>null</code>, and <code>paths</code> lists normalized accepted targets. Hashes describe original bytes before redaction, so they need not match the redacted content. The collector preserves provenance instead of deciding which conflicting prose wins.</p><p>Before direct writes or shell work in a new subtree, obtain context for that path. For example, the model makes these tool calls in order (using the id from <code>create_workspace</code>):</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span>read_repository_instructions({ paths: [&#39;packages/api/src/new.ts&#39;], workspace: &#39;workspace-id&#39; })</span></span>
<span class="line"><span>// Examine sources and diagnostics; resolve incomplete guidance before continuing.</span></span>
<span class="line"><span>bash({ command: &#39;git diff -- packages/api/src/new.ts&#39;, workspace: &#39;workspace-id&#39; })</span></span></code></pre></div><p>This works before <code>new.ts</code> exists. Include paths for every subtree a command will touch; shell state or <code>cwd</code> alone does not collect guidance. Downstream agent prompts should request this workflow and stop for incomplete guidance that could change the task.</p><p>A source is returned whole or omitted: at most 32 KiB each, 128 KiB together and 32 sources, 8 include edges deep. Each request permits 32 target paths, 64 distinct ancestor directories including root, 512 attempted inspections/include references and 4096 UTF-8 bytes per path. Diagnostics are capped at 64 entries and 8 KiB of paths and messages; the request at 30 seconds, each exec at 5 seconds. Missing optional entrypoints are normal. Missing includes, unreadable files, invalid UTF-8, refused paths, cycles and bounds produce diagnostics and <code>complete: false</code>. Cancellation, workspace/transport failures, malformed responses and missing inspection capabilities are tool errors. See the <a href="/reference/sandbox#repository-instructions">sandbox reference</a> for diagnostic codes and exact public interfaces.</p><p>Each create (including reuse or adoption after recovery), explicit context call and applicable file read re-collects the current worktree. Changes to instruction files appear on the next collection; older checkpointed messages keep their original content. There is no cross-call cache or transactionally frozen checkout.</p><p>Two independent options default to <code>true</code>: <code>createWorkspaceManager({ provider, repositoryInstructions: false })</code> disables automatic root collection (<code>instructions: null</code>) and removes the explicit tool; <code>codingTools(manager, { repositoryInstructions: false })</code> omits text-read attachments. Disabling only one leaves the other enabled. <code>sandboxModule({ repositoryInstructions: false })</code> forwards the manager option; there is no environment variable. These flags control delivery, not filesystem access.</p><p>Repository text is development guidance, not operator authorization. A system prompt does not enforce permissions; guidance cannot enable tools, credential access, skill installation or publication. <code>write_file</code>, <code>edit_file</code>, <code>multi_edit</code> and arbitrary <code>bash</code> do not enforce instruction scope, and bash bypasses file-tool-only enforcement. Discovery runs fixed framework scripts, never repository programs or commands from Markdown, and refuses observed symlink components (including in-workspace aliases), special files, <code>.git</code> paths and escapes. These are best-effort checks against the observed filesystem; concurrent changes can race them. Strict race-free confinement is deferred to <a href="https://github.com/chamvi/chamvi/issues/92" target="_blank" rel="noreferrer">#92</a>.</p><h2 id="git-and-credentials" tabindex="-1">Git and credentials <a class="header-anchor" href="#git-and-credentials" aria-label="Permalink to &quot;Git and credentials&quot;">​</a></h2><p>A checkout has the full history of <code>ref</code> and the remote&#39;s default branch fetched next to it (<code>origin/&lt;defaultBranch&gt;</code>), so the model can merge or rebase onto the base branch; a branch is checked out tracking <code>origin/&lt;branch&gt;</code>, a tag or commit detached. <code>depth</code> on the manager makes it shallow for huge repositories.</p><p>Private repositories and pushes need credentials. The manager asks its <code>credentials</code> sources in order, the first answer wins, none is anonymous:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> workspaces = createWorkspaceManager({</span></span>
<span class="line"><span style="color:#E6DFDE;">    provider,</span></span>
<span class="line"><span style="color:#E6DFDE;">    credentials: [</span></span>
<span class="line"><span style="color:#958A8B;">        // a GitLab project token for one group</span></span>
<span class="line"><span style="color:#E6DFDE;">        staticGitCredentials([{</span></span>
<span class="line"><span style="color:#E6DFDE;">            host: </span><span style="color:#E7C58C;">&#39;gitlab.example.com&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            path: </span><span style="color:#E7C58C;">&#39;platform&#39;</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">            token: process.env.GITLAB_TOKEN</span><span style="color:#FF7B84;">!</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">        }]),</span></span>
<span class="line"><span style="color:#958A8B;">        // the GitHub App&#39;s repository-scoped tokens, allowed to touch workflows</span></span>
<span class="line"><span style="color:#E6DFDE;">        githubAppCredentials(app, { permissions: { workflows: </span><span style="color:#E7C58C;">&#39;write&#39;</span><span style="color:#E6DFDE;"> } }),</span></span>
<span class="line"><span style="color:#E6DFDE;">    ],</span></span>
<span class="line"><span style="color:#958A8B;">    // plain git in bash authenticates; issued tokens are redacted from results</span></span>
<span class="line"><span style="color:#E6DFDE;">    author: </span><span style="color:#FF7B84;">await</span><span style="color:#E6DFDE;"> app.botIdentity(),</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><ul><li><code>staticGitCredentials([{ host, path?, username?, token }])</code>: personal access tokens of GitHub (<code>x-access-token</code>), GitLab (<code>oauth2</code>, also project and deploy tokens) or any https host; <code>path</code> narrows a token to an owner or a repository (case-insensitive, like GitHub&#39;s and GitLab&#39;s paths), the longest match wins. <code>sandboxModule()</code> also reads them as JSON from <code>CHAMVI_GIT_TOKENS</code>.</li><li><code>githubAppCredentials(app, { permissions? })</code> (<code>@chamvi/github</code>): a token of the App&#39;s installation limited to the one repository, <code>contents: read</code> to read, <code>contents: write</code> plus <code>permissions</code> (e.g. <code>{ workflows: &#39;write&#39; }</code>, which a change under <code>.github/workflows</code> needs) to push, cached until shortly before it expires. <code>githubModule()</code> contributes it to <code>sandboxModule()</code> on its own (<code>credentials: false</code> turns that off), and <code>app.botIdentity()</code> gives the bot&#39;s commit identity for <code>author</code>.</li></ul><p>Credentials are installed in the workspace&#39;s HOME through a helper and a 0600 file under <code>$HOME/.chamvi/</code>. The read credential is installed before private checkout; the manager then installs the repository&#39;s write credential (falling back to read) and a read credential for the host. Plain <code>git</code> in <code>bash</code>, including private dependency fetches, authenticates through this helper. Tokens are refreshed before a command once one expires within ten minutes, with concurrent refreshes shared and retries at least a minute apart. Found workspaces are reinstalled rather than reading back a model-writable credentials file.</p><p>Issued tokens are redacted from results, file reads and errors (<code>[redacted]</code>, until an hour after expiry); <code>edit_file</code>, <code>multi_edit</code> and <code>write_file</code> put untouched raw credentials back (a <code>write_file</code> whose <code>[redacted]</code> markers do not line up with the file&#39;s is refused). Redaction is not secret isolation: sandbox code can read and transform the credentials. It is also process-local: after a restart, or on another replica, a workspace found again redacts only the tokens the current process issued, so a token an earlier process installed can show up unredacted until the next install overwrites it. Token permissions, installation scope, branch protection and required checks with no App bypass are the real controls. <code>author: { name, email }</code> sets <code>GIT_AUTHOR_*</code> and <code>GIT_COMMITTER_*</code>.</p><p>Use ordinary <code>git fetch</code>, <code>git pull</code>, <code>git push</code> and <code>gh</code> through <code>bash</code>. The default sandbox-dev image includes GitHub CLI from its official apt repository (the current release at build time, so the weekly rebuild picks up fixes; pin the image digest for a fixed version). Git&#39;s helper does not automatically authenticate <code>gh</code>; supply GitHub CLI authentication separately under your operator policy. No credentials are baked into the image. Durable <code>approve()</code> and effect tools remain available, but an agent&#39;s decision to ask before a bash write is advisory, not an enforced write boundary.</p><h3 id="migration-from-tools-only-credentials" tabindex="-1">Migration from tools-only credentials <a class="header-anchor" href="#migration-from-tools-only-credentials" aria-label="Permalink to &quot;Migration from tools-only credentials&quot;">​</a></h3><p>Remove <code>credentialMode</code>, its <code>CredentialMode</code> type and <code>CHAMVI_GIT_CREDENTIAL_MODE</code>. Workspace-installed credentials are the only mode; a set <code>CHAMVI_GIT_CREDENTIAL_MODE</code> or a <code>credentialMode</code> option is refused with <code>InvalidAgentDefinitionError</code> instead of being ignored (a former <code>tools</code> mode would otherwise hand <code>bash</code> the write token). The structured Git tools, their result types and <code>PushPolicy</code> remain available. Push checks govern <code>git_push</code> only; sandbox code with another execution path can bypass them.</p><h2 id="lifecycle" tabindex="-1">Lifecycle <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;Lifecycle&quot;">​</a></h2><p>A workspace is keyed by run and repository, and its lifetime follows the run up to a hard cap: a container sleeps until its expiry (also when it is started again after a host restart) and a pod likewise (<code>lifetimeSeconds</code> as its <code>activeDeadlineSeconds</code> beside it, so a pod scheduled late still stops at its expiry), so it stops itself at its expiry even when nothing collects it, while nothing kills it earlier, also through a 24 hour approval. It lives until the first of:</p><ul><li>the run settles: <code>completed</code>, <code>failed</code> or <code>cancelled</code> (through <code>workspaces.attach(engine)</code>, also for the workspaces another replica created: with <code>isSettled</code> those go with the garbage collection a settled run starts, at most one per 10 minutes). A run <code>waiting</code> for an approval or <code>interrupted</code> keeps its workspaces.</li><li><code>dispose_workspace</code>, or <code>workspaces.release(runId, id?)</code></li><li>its hard cap, <code>limits.maxLifetimeMs</code> (default 7 days from its creation, never renewed), checked on every use</li><li>it was found gone and nothing finds it again: its container was removed, its pod failed, was evicted or deleted, or its local directory was removed. The call that found it says &quot;workspace ... is gone; call create_workspace for a new one&quot;; the next call asks the provider again (a stopped container comes back, see below), and <code>create_workspace</code> creates a new one when nothing is found</li><li>garbage collection: <code>sandboxModule()</code> runs <code>workspaces.collectGarbage()</code> every 10 minutes in start mode (<code>gcIntervalMs</code>, on the engine&#39;s clock), and <code>acquire</code> (and a settled run <code>attach</code> sees) at most every 10 minutes. It removes expired workspaces and, with <code>isSettled</code> (which <code>sandboxModule()</code> answers through the engine), those whose run settled, also when the replica that ran it was down; with a named deployment (see below) also those whose run no longer exists</li></ul><p><strong>A run finds its workspaces again</strong> after an approval pause, a restart or on another replica of the same Docker host or Kubernetes cluster: on a miss the manager asks the provider (<code>find</code>) for the run&#39;s workspaces by label (local: the folder records) and adopts them, with their files, repository and ref. A stopped Docker container (a host or daemon restart) is started again; its volume still holds the work. That holds in the process that held it too: the call that hit the stopped container fails as gone, and the manager forgets the workspace without removing it, so the next call finds it again, restarted. Moving a workspace between hosts is not supported.</p><p><code>workspaces.close()</code> at shutdown (call it <strong>after</strong> <code>engine.drain()</code>) disposes nothing a live run holds (<code>close({ dispose: true })</code> disposes those too, which <code>sandboxModule()</code> does when <code>engine.store.runs</code> is a <code>MemoryRunRepository</code>, since no run of it resumes after the restart): it aborts the creates still in flight (disposing what they made) and waits for them and for every disposal already started, at most 30 seconds (<code>close({ timeoutMs })</code>), then reports what is left to <code>onError</code>.</p><p>Several deployments (dev and prod, CI) may share one Docker host or namespace: every workspace carries the manager&#39;s <code>deployment</code> (<code>CHAMVI_DEPLOYMENT</code> with the module, default <code>default</code>), and <code>find</code> and the garbage collection only see their own. Give every app on a shared host its own <code>CHAMVI_DEPLOYMENT</code>: <code>sandboxModule()</code> treats a run its engine does not know as finished only in a named deployment, since in <code>default</code> that run may belong to another app. So with the default, the workspaces of runs the store no longer holds (an app using <code>createMemoryStore()</code> that crashed instead of stopping) stay until <code>maxLifetimeMs</code>; with a named deployment they go on the next collection, and two apps sharing one name remove each other&#39;s workspaces.</p><p>For development, the local provider runs everything in a temporary directory:</p><div class="language-ts"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki chamvi vp-code" tabindex="0"><code><span class="line"><span style="color:#958A8B;">// no isolation: commands run as your user in a temporary directory</span></span>
<span class="line"><span style="color:#FF7B84;">const</span><span style="color:#E6DFDE;"> workspaces = createWorkspaceManager({</span></span>
<span class="line"><span style="color:#E6DFDE;">    provider: createLocalSandbox(),</span></span>
<span class="line"><span style="color:#958A8B;">    // local fixtures as file:///absolute/path repositories</span></span>
<span class="line"><span style="color:#E6DFDE;">    allowFileRepos: </span><span style="color:#FF7B84;">true</span><span style="color:#E6DFDE;">,</span></span>
<span class="line"><span style="color:#E6DFDE;">});</span></span></code></pre></div><h2 id="the-shell" tabindex="-1">The shell <a class="header-anchor" href="#the-shell" aria-label="Permalink to &quot;The shell&quot;">​</a></h2><p><code>bash</code> behaves like a terminal tab. The working directory and the exported variables carry over from one call to the next: <code>cd src</code> in one call, <code>npm test</code> in the next runs in <code>src</code>; <code>export NODE_ENV=test</code> stays set. The result&#39;s <code>cwd</code> is where the next call starts. A <code>cwd</code> argument runs that one call elsewhere and leaves the kept directory alone. The command runs in bash when the image has it, else in <code>sh</code>. An <code>exit 1</code>, a failed <code>cd</code> or <code>set -e</code> keep the state consistent; functions, aliases and shell options are not kept, and neither is the <code>unset</code> of a variable the workspace started with. A call that timed out keeps the state from before it.</p><p>The whole output of every call goes to <code>~/.chamvi/out/&lt;id&gt;.stdout.log</code> and <code>.stderr.log</code> (<code>stdoutLog</code>, <code>stderrLog</code>), outside <code>/workspace</code>; the newest 100 logs are kept, and older ones go once the logs take more than four times <code>outputLogMaxBytes</code> (256 MiB by default; the logs of a call still running always stay, also those of a parallel call), since <code>HOME</code> shares the workspace&#39;s disk. A call that cannot write its logs or its report (no space left in <code>HOME</code>, or a folder that takes no file) is a <code>SandboxError</code> saying so, never a garbled result. Up to 32 KiB per stream the result holds all of it; past that the first 8 KiB and the last 24 KiB with a <code>[... &lt;n&gt; bytes cut, full output in &lt;log&gt;]</code> line between them, so a long test run still shows the summary at its end. <code>read_file</code> reads a log by line range, <code>grep</code> searches it, and <code>bash</code> can <code>tail</code> it.</p><p>Servers and watchers run as <strong>background jobs</strong>: <code>bash({ command: &#39;npm run dev&#39;, background: true })</code> returns <code>{ job, status: &#39;running&#39; }</code> at once. <code>bash_output({ job, offset? })</code> returns the job&#39;s new output (stdout and stderr together, at most 32 KiB from <code>offset</code>; pass <code>nextOffset</code> to read on) and its status (<code>running</code>, <code>exited</code> with the exit code, <code>killed</code>, or <code>lost</code> after a container restart); a job whose output passes <code>outputLogMaxBytes</code> is killed with every process it started (checked every second, <code>outputCapped: true</code>, status <code>killed</code>) and its output cut back to the cap; <code>bash_kill({ job })</code> stops it with every process it started (TERM, then KILL after 3 seconds). A job lives in a process group of its own and dies with the workspace; on local, also with the chamvi process. Docker workspaces run <code>docker-init</code> as PID 1 (<code>Init: true</code>) and Kubernetes pods share the process namespace with the pause container, so the processes a job or a call leaves behind are reaped whatever the image (an image without <code>tini</code> runs <code>sleep</code> as PID 1, which reaps nothing, so every orphan would stay a zombie and count against the pid limit).</p><p><code>HOME</code> is <code>/home/sandbox</code> in every container and pod (<code>WORKSPACE_HOME</code>, a disk-backed volume of the workspace), so the shell state, the logs and the jobs survive a container restart and never fill the memory-backed <code>/tmp</code>. Local keeps <code>&lt;root&gt;/&lt;id&gt;/home</code>.</p><h2 id="commands-output-and-timeouts" tabindex="-1">Commands, output and timeouts <a class="header-anchor" href="#commands-output-and-timeouts" aria-label="Permalink to &quot;Commands, output and timeouts&quot;">​</a></h2><ul><li><code>exec</code> takes <strong>argv only</strong>; the only shells are the coding tools&#39; <code>sh -c</code> scripts inside the workspace, which take the command as an argument, never pasted into the script.</li><li><code>exec</code> caps stdout and stderr at 64 KiB each (<code>stdoutTruncated</code>, <code>stderrTruncated</code>); output past the cap is drained, never buffered, so <code>yes</code> cannot block the child or fill the host&#39;s memory. The <code>bash</code> tool writes the output to its log files instead, each capped at 64 MiB (<code>codingTools(manager, { outputLogMaxBytes })</code>): a command whose log passes the cap is killed with its jobs like a timeout (<code>outputCapped: true</code>) and the log keeps its first 64 MiB. A <code>background: true</code> job is capped the same way (see above). A process the command leaves running (<code>cmd &amp;</code>) is watched after the call too: it is killed with its process group once its log passes the cap, or once the log rotation of later calls (the newest 100 logs are kept, about 50 calls) deletes its logs. For a long-running server use <code>background: true</code>, whose output <code>bash_output</code> can read.</li><li>A command times out after <code>timeoutMs</code> (default 5 minutes, at most 30, never past the workspace&#39;s hard cap) with <code>timedOut: true</code> as a result, not an error. The whole process group is killed, background jobs included: local sends <code>SIGKILL</code> to the group, Docker and Kubernetes run every command inside GNU <code>timeout -k 5</code>. A command that exits on its own returns with its exit code even when a background job it started (<code>node server.js &amp; echo started</code>) holds its output (after about 2 seconds); the job runs on until the workspace is disposed, so the next call can probe the server.</li><li>A <code>cwd</code> that is no directory in the workspace rejects with a <code>SandboxError</code> on every provider.</li><li><strong>Abort</strong> (a cancelled run, a run timeout): local kills the process group. Docker and Kubernetes <strong>detach</strong>: the client stops waiting, and the command runs on until its <code>timeout</code> fires or the workspace is disposed, which the settled run&#39;s <code>attach</code> does right after.</li><li>A sandbox failure (a failed create or checkout, an unknown or expired workspace, a daemon or API error) is a <code>SandboxError</code>: a tool error the model sees, never a failed run.</li></ul><h2 id="why-the-coding-tools-are-not-effect-tools" tabindex="-1">Why the coding tools are not effect tools <a class="header-anchor" href="#why-the-coding-tools-are-not-effect-tools" aria-label="Permalink to &quot;Why the coding tools are not effect tools&quot;">​</a></h2><p><code>write_file</code>, <code>edit_file</code>, <code>bash</code>, <code>create_workspace</code> and <code>dispose_workspace</code> change state, yet they are plain <a href="/guide/tools"><code>defineTool()</code></a> tools, not <a href="/guide/effect-tools">effect tools</a>. An effect record lives in the store forever; a workspace can be removed, expire or be collected. A redone step could then run on a fresh workspace, where a recorded &quot;applied&quot; result would skip the write and leave the workspace and the history out of step. Effect tools would also merge two identical calls of one step (<code>npm test</code> twice) into one.</p><p>Re-applying is safe instead: <code>write_file</code> is idempotent, <code>edit_file</code> and <code>multi_edit</code> fail with &quot;oldString not found&quot; when it already applied (the model sees that), and <code>bash</code> runs in a disposable sandbox. Nothing outside the workspace changes.</p><h2 id="security-model" tabindex="-1">Security model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security model&quot;">​</a></h2><ul><li><strong>The model runs untrusted code.</strong> Whatever it reads (an issue body, a README, a test&#39;s output) can steer what it runs: prompt injection. Run untrusted repositories on Docker or Kubernetes, never local, narrow <code>allowRepo</code>, and put <code>bash</code> behind an <a href="/guide/approvals#gating-tools-you-did-not-write">approval</a> (a <code>beforeToolExecution</code> hook calling <code>approve()</code>, as above) where a human should see each command.</li><li><strong>Local isolates nothing.</strong> Commands run as the host user with your files and network in reach. It only keeps the host environment out (just <code>PATH</code>, its own <code>HOME</code> and <code>TMPDIR</code>) and kills process groups. Background jobs die with the process (on its <code>exit</code>): after a restart a local workspace keeps its files but not its jobs, and a process killed with SIGKILL leaves them running.</li><li><strong>Docker and Kubernetes enforce</strong> the container boundary: no privileged mode, only the package-manager capabilities (none in the hardened mode, which also drops root and makes the root filesystem read-only), no privilege escalation, no host mount but the cache, cpu and memory limits (pids on Docker, the kubelet&#39;s <code>podPidsLimit</code> on Kubernetes; storage on Kubernetes), a hard lifetime cap through the garbage collection, and no host or chamvi environment. Kubernetes mounts no service account token.</li><li><strong>Credentials</strong>: tokens are installed in the workspace and redacted from results, not isolated from sandbox code. Transformed or split tokens can escape whole-value redaction. Keep credentials out of URLs and enforce authorization with scoped grants and forge rules.</li><li><strong>A sandbox is a code-execution boundary, not a network boundary.</strong> On a Docker bridge a workspace reaches the host gateway (the chamvi API, Postgres, an MCP server), other containers and cloud metadata (<code>169.254.169.254</code>); on Kubernetes every service in the cluster. Until the Helm chart&#39;s NetworkPolicy ships, add one yourself (select <code>app.kubernetes.io/component=sandbox</code>, allow only GitHub and the npm registry, deny the chamvi namespace and the metadata address), or on Docker a network with <code>enable_icc=false</code> plus host firewall rules.</li><li><strong>Docker socket access is root on the host.</strong> Give chamvi a socket proxy or rootless Docker rather than the raw socket.</li></ul><h3 id="structured-git-tools-and-policy-scope" tabindex="-1">Structured Git tools and policy scope <a class="header-anchor" href="#structured-git-tools-and-policy-scope" aria-label="Permalink to &quot;Structured Git tools and policy scope&quot;">​</a></h3><p><code>manager.tools()</code> includes <code>git_fetch</code>, <code>git_pull</code> and <code>git_push</code> without granting a bash tool. They retain structured results, per-target credential lookup, force-with-lease, branch checks and the optional durable approval flow through <code>push: { mode: &#39;approve&#39;, channel?, allowBranch?, allowForce? }</code>. In a tainted run <code>git_push</code> asks once: the untrusted-content gate&#39;s approval (private, in the inbox and API, with only a generic notice on the run&#39;s source channel) carries the same <code>Push &lt;n&gt; commits to &lt;branch&gt;</code> title and commit log, and the push asks nothing more, so <code>push.channel</code> is not asked in a tainted run. A push the policy refuses (a force push without <code>allowForce</code>, a branch <code>allowBranch</code> refuses) is denied before the gate asks. These checks apply only to <code>git_push</code>: bash with write credentials can bypass them. Disabling bash narrows the offered capabilities, but writable Git configuration, hooks and other indirect execution still require a threat model; the tools are not a credential-secrecy boundary. Enforce hard restrictions through token scope and forge rules.</p>`,70)])])}const m=o(n,[["render",c]]);export{u as __pageData,m as default};
